        items: ['NVIDIA — GB200, B300, H100, A100 e GPUs de consumo', 'AMD — séries MI300 e MI355', 'TPUs do Google — via backend SGLang-JAX', 'CPUs Intel Xeon — caminho de suporte documentado', 'NPUs Ascend — caminho de suporte documentado'],
